"""Build article pages and the homepage newspaper from the editable story registry."""
from pathlib import Path
from html import escape as e
from datetime import date
import json
import sys
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from news_quiz import render_news_questions
root=Path(__file__).resolve().parent.parent
stories=json.loads((root/'articles/stories.json').read_text())
home=(root/'index.html').read_text()
header=home[home.index('<header '):home.index('</header>')+9].replace('href="#','href="/#')
footer=home[home.index('<footer '):home.index('</footer>')+9]
for story in stories:
 s=story;slug=s['slug'];published=date.fromisoformat(s['date']).strftime('%B %d, %Y').replace(' 0',' ')
 sources=''.join(f'<li><a href="{e(url)}" target="_blank" rel="noopener noreferrer">{e(label)} ↗</a></li>' for label,url in s['sources'])
 credit=f'<a href="{e(s["image_source"])}">{e(s["artist"])} / Wikimedia Commons</a> · <a href="{e(s["license_url"])}">{e(s["license"])}</a>. Responsive display may crop the image.'
 related=''.join(f'<a href="/articles/{e(t["slug"])}"><span>{e(t["category"])}</span><h3>{e(t["short_title"])}</h3><span>Read the story ↗</span></a>' for t in stories if t!=s)
 output=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{e(s['deck'])}"><meta property="og:title" content="{e(s['title'])}"><meta property="og:description" content="{e(s['deck'])}"><meta property="og:image" content="https://tmrceo.com/assets/news/{e(s['image'])}"><meta property="og:type" content="article"><meta property="article:published_time" content="{s['date']}T00:00:00Z"><link rel="canonical" href="https://tmrceo.com/articles/{slug}"><title>{e(s['title'])} · The Tomorrow Times</title><link rel="stylesheet" href="/styles.css"></head><body>{header}<main class="story-page wrap"><a class="back-news" href="/#news">← Back to The Tomorrow Times</a><div class="story-kicker">THE TOMORROW TIMES · {e(s['category'])}</div><article><header class="story-heading"><h1>{e(s['title'])}</h1><p class="story-deck">{e(s['deck'])}</p><div class="story-meta">By {e(s['author'])} <span>·</span> <time datetime="{s['date']}">{published}</time><span>·</span> 2 min read</div></header><figure class="story-hero {slug}"><img src="/assets/news/{e(s['image'])}" alt="{e(s['alt'])}" width="1200" height="800"><figcaption>{e(s['caption'])}<br>{credit}</figcaption></figure><div class="story-body">{s['body']}<section class="wonder-box"><span class="eyebrow">TAKE A QUESTION WITH YOU</span><h2>{e(s['question'])}</h2><a class="text-link" href="/#share-discovery">Share something you learned ↗</a></section><section class="story-sources"><h2>Keep exploring</h2><p>Sources checked October 16, 2026. Publication dates refer to our articles, not when the facts were discovered.</p><ul>{sources}</ul></section></div></article><aside class="related"><span class="eyebrow">MORE FROM OUR LITTLE NEWSPAPER</span><div>{related}</div></aside></main>{footer}</body></html>'''
 (root/'articles'/f'{slug}.html').write_text(output)
card_html=[]
for i,s in enumerate(stories):
 card_date=date.fromisoformat(s['date']).strftime('%b %d, %Y').upper().replace(' 0',' ')
 card_html.append(f'''<article class="news-card {'lead-story' if i==0 else ''}"><a href="/articles/{s['slug']}"><figure class="news-image {s['slug']}"><img src="/assets/news/{s['image']}" alt="{e(s['alt'])}" loading="lazy" width="800" height="530"></figure><span class="news-category">{e(s['category'])}</span><h3>{e(s['short_title'])}</h3><p>{e(s['deck'])}</p><div class="news-byline">By {e(s['author'])}</div><div class="news-meta"><time datetime="{s['date']}">{card_date}</time><span>READ THE STORY ↗</span></div></a></article>''')
section='''<!-- newspaper:start -->
<section class="newspaper wrap" id="news" aria-labelledby="news-title"><div class="paper-strap"><span>VOL. 01 · THE CURIOSITY EDITION</span><span>A LITTLE WISER, TOGETHER.</span></div><header class="paper-masthead"><span class="paper-star" aria-hidden="true">✳</span><div><p>A SMALL PAPER FOR BIG QUESTIONS</p><h2 id="news-title">The Tomorrow Times</h2><p>Things we learned. Things worth sharing.</p></div><span class="paper-star" aria-hidden="true">✳</span></header><div class="paper-dateline"><time datetime="2026-10-16">FRIDAY, OCTOBER 16, 2026</time><span>NATURE · IDEAS · LITTLE DISCOVERIES</span><span>ISSUE NO. 001</span></div><div class="news-grid">'''+''.join(card_html)+'''</div>'''+render_news_questions()+'''<div class="paper-end"><p><strong>The world is full of “wait, really?”</strong> These are four of ours. What have you learned lately?</p><a href="#share-discovery" class="text-link">Send a little discovery ↗</a></div><details class="discovery-submit" id="share-discovery"><summary>Something surprised you? Share it with our little newsroom <span aria-hidden="true">+</span></summary><div class="discovery-inner"><h3>Your curiosity belongs here.</h3><p>Everyone is welcome to be a journalist. What did you learn that was exciting today? Share your discovery and its source so we can learn from each other. Our newsroom reviews and proofreads every submission for accuracy and suitability for kids before publication. Published posts include an author credit and date. Good questions, thoughtful stories. No brain rot.</p><form id="discovery-form"><div class="discovery-fields"><label>A name or nickname <span>(optional)</span><input name="name" maxlength="60" autocomplete="nickname" placeholder="What should we call you?"></label><label>Your headline<input name="title" maxlength="140" required placeholder="Do you know…?"></label></div><label>What did you learn?<textarea name="fact" rows="4" maxlength="3000" required placeholder="Tell us the interesting bit, in your own words."></textarea></label><label>Where can we learn more?<input name="source" type="url" maxlength="1000" required placeholder="https://…"></label><div class="honey" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input type="checkbox" name="consent" required><span>I’m happy for tmrCEO to review this and, if selected, publish my discovery with the name I supplied. I won’t include private information.</span></label><button class="button dark" type="submit">Send to the newsroom ↗</button><p id="discovery-status" role="status" aria-live="polite"></p></form></div></details></section>
<!-- newspaper:end -->'''
if '<!-- newspaper:start -->' in home:
 start=home.index('<!-- newspaper:start -->');end=home.index('<!-- newspaper:end -->')+len('<!-- newspaper:end -->');home=home[:start]+section+home[end:]
else:
 home=home.replace('<div class="ticker"',section+'\n<div class="ticker"',1)
(root/'index.html').write_text(home)
print('Built four article pages and homepage newspaper.')
